window.__finlexDocLoaded(10022,{"id":10022,"articles":[{"id":1000115,"no":"Overview","heading":"Official Overview & Objective (IASB, May 2026)","text":"In May 2026, the International Accounting Standards Board (IASB) issued IFRS 20 Regulatory Assets and Regulatory Liabilities. IFRS 20 supersedes IFRS 14 Regulatory Deferral Accounts and fills a gap in IFRS Accounting Standards for entities subject to rate regulation.\n\nObjective: Provide investors with transparent, comparable information about the effects of regulatory income, regulatory expense, regulatory assets and regulatory liabilities on an entity's financial performance and financial position.","seq":0},{"id":1000116,"no":"Official PDFs","heading":"Open Official IFRS Foundation Documents","text":"Official Press Release (May 27, 2026): https://www.ifrs.org/news-and-events/news/2026/05/iasb-issues-ifrs-20/\nProject Summary (Open PDF): https://www.ifrs.org/content/dam/ifrs/project/rate-regulated-activities/standard/iasb-ifrs20-projectsummary.pdf\nFeedback Statement (Open PDF): https://www.ifrs.org/content/dam/ifrs/project/rate-regulated-activities/standard/iasb-ifrs20-fbs.pdf\nAt a Glance One-Pager (Open PDF): https://www.ifrs.org/content/dam/ifrs/project/rate-regulated-activities/standard/iasb-ifrs20-one-page.pdf","seq":1},{"id":1000117,"no":"Big Four Guide","heading":"Public Practical Guidance (EY)","text":"EY — Applying IFRS: A Closer Look at IFRS 20 (September 2026, Open PDF):\nPage: https://www.ey.com/en_gl/technical/ifrs-technical-resources/applying-ifrs-a-closer-look-at-ifrs-20\nPDF: https://www.ey.com/content/dam/ey-unified-site/ey-com/en-gl/technical/ifrs-technical-resources/documents/ey-gl-applying-ifrs-20-september-2026.pdf","seq":2}]});
